}

"""Return the number from its prime factors.

Args:
    factors: Dictionary of prime factors (keys) and their exponents (values).
Returns:
    An integer. The number made of the prime factors.
Usage:
    >>> calcDivisor({5: 3, 7: 2})
    6125
    >>> calcDivisor({2: 3, 5: 2, 7: 1})
    1400
"""
def calcDivisor(factors: dict[int, int]) -> int {
    acc = 1;
    for (f, e) in factors.items() {
        acc *= f ** e;
    }
    return acc;
}

"""Compare elements that have changed between prev_hash_dict and current_hash_dict.

    Check if any elements have been added, removed or modified.
    """
def compare_elements(prev_hash_dict: dict[str, str], current_hash_dict: dict[str, str]) -> dict[str, str] {
    changed = {};
    for key in prev_hash_dict {
        elem = current_hash_dict.get(key, '');
        if elem == '' {
            changed[key] = 'deleted';
        } elif elem != prev_hash_dict[key] {
            changed[key] = 'changed';
        }
    }
    for key in current_hash_dict {
        elem = prev_hash_dict.get(key, '');
        if elem == '' {
            changed[key] = 'added';
        }
    }
    return changed;
}

