""" Enclose the string argument in single quotes if it looks like it needs it.
        Spaces and quotes will trigger; single quotes in the argument are escaped.
        This is only used to compose the --print output so need only satisfy shlex.
    """
def maybe_quote(s: str) -> str {
    NEED_QUOTE = " \t\"\\'";
    clean = True;
    for c in s {
        if c in NEED_QUOTE {
            clean = False;
            break;
        }
    }
    if clean {
        return s;
    }
    QUOTE = "'";
    ESC = "\\";
    arg = [QUOTE];
    for c in s {
        if c == QUOTE {
            arg.append(QUOTE);
            arg.append(ESC);
            arg.append(QUOTE);
        } elif c == ESC {
            arg.append(ESC);
        }
        arg.append(c);
    }
    arg.append(QUOTE);
    return ''.join(arg);
}

"""
    Estimate whether a feature is discrete given the number of records
    observed and the cardinality (number of unique values)

    The default assumption is that features are not discrete.
    """
def is_discrete(num_records: int, cardinality: int, p: float = 0.15) -> bool {
    if cardinality >= num_records {
        return False;
    }
    if num_records < 1 {
        return False;
    }
    if cardinality < 1 {
        raise ValueError("Cardinality must be >= 1 for num records >= 1");
    }
    discrete = False;
    density = num_records / (cardinality + 1);
    if 1 / density <= p {
        discrete = True;
    }
    return discrete;
}

