"""Moving elements to left and right to pivot to make sure arr[pi] is at the right position
Input:
    - arr: array to be sorted
    - start: start position/index
    - end: end position/index
Return: pi"""
def partition(arr: list, start: int, end: int) -> int {
    pivot = arr[end];
    small = start - 1;
    for i in range(start, end) {
        if arr[i] <= pivot {
            small += 1;
            (arr[small], arr[i]) = (arr[i], arr[small]);
        }
    }
    small += 1;
    (arr[small], arr[end]) = (arr[end], arr[small]);
    return small;
}

