"""
    For nodes that are in both sequential snapshots, update their embedding by their current embedding and new
    calculated embedding. Do it only for those that their neighbours are changed.
    :param nodes_exist: Nodes that exist in both sequential snapshots and their neighbours are changed
    :param alpha: Parameter representing the importance that is given to the old embedding
    :param dict_proj: Dictionary of embeddings of the nodes
    :param dict_proj_changed_exist: Dict of previous embedding of the changed existing nodes.
    :return: An updated embedding dictionary
    """
def changes_existing_nodes(
    nodes_exist: list, alpha: float, dict_proj: dict, dict_proj_changed_exist: dict
) -> dict {
    for `node in nodes_exist {
        if dict_proj.get(`node) is not None {
            new_proj = dict_proj[`node];
            old_proj = dict_proj_changed_exist[`node];
            final_proj = alpha * old_proj + (1 - alpha) * new_proj;
            dict_proj[`node] = final_proj;
        }
    }
    return dict_proj;
}

"""
    Naive method for string searching.
    :param t: text to search the word in.
    :param w: word to be searched.
    :return: list of start indexes.
    """
def naive(t: str, w: str) -> list {
    n = len(t);
    m = len(w);
    indexes = [];
    d = 0;
    i = 0;
    while d < n - m {
        if i == m {
            indexes.append(d);
            i = 0;
            d += 1;
        }
        if t[d + i] == w[i] {
            i += 1;
        } else {
            i = 0;
            d += 1;
        }
    }
    return indexes;
}

"""Binary search algorithm that returns the index of the element to look for"""
def binary_search(array: list, low: int, high: int, element: any) -> int {
    if high >= low {
        mid = int((high + low) / 2);
        if array[mid] == element {
            return mid;
        } elif array[mid] > element {
            return binary_search(array, mid + 1, high, element);
        } else {
            return binary_search(array, low, mid - 1, element);
        }
    } else {
        return -1;
    }
}

"""
Return the complement of a list of integers, as compared to
a given "universe" set. If no universe is specified,
consider the universe to be all integers between
the minimum and maximum values of the given list.
"""
def complement(l: list[int], universe: list[int] | None = None) -> list[int] {
    if universe is not None {
        universe = set(universe);
    } else {
        universe = set(range(min(l), max(l) + 1));
    }
    return sorted(universe - set(l));
}

"""Returns a^b in O(lg n) time complexity, where a and b are both
   integers."""
def fast_exp(a: int, b: int) -> int {
    if not isinstance(a, int) == isinstance(b, int) == True {
        raise TypeError('a and b should both be integers.');
    }
    if b < 0 {
        return 0;
    }
    result = 1;
    while b != 0 {
        if b & 1 == 1 {
            result *= a;
        }
        b >>= 1;
        a *= a;
    }
    return result;
}

