"""Parses duration value string 'Xhr', 'Ymin' or 'Zsec' and returns (X::Y::Z) as seconds"""
def parse_duration(row: str) -> int {
    import re;
    def filter_digits(s: str) -> str {
        return "".join(re.findall('\d+', s));
    }
    seconds = 0;
    if 'hr' in row {
        (hr, row) = row.split('hr');
        seconds += int(filter_digits(hr)) * 3600;
    }
    if 'min' in row {
        (min, row) = row.split('min');
        seconds += int(filter_digits(min)) * 60;
    }
    if 'sec' in row {
        (sec, _) = row.split('sec');
        seconds += int(filter_digits(sec));
    }
    return seconds;
}

"""GCD(x:int, y:int): int
    Return the GCD of x and y.
    """
def GCD(x: int, y: int) -> int {
    x = abs(x);
    y = abs(y);
    while x > 0 {
        (x, y) = (y % x, x);
    }
    return y;
}

""" Returns a list of times when the signal goes high using a software schmitt trigger.
    Input:
        evelope: the envelope of the signal to process
        high_theshold_ratio: ratio of the max of the signal to trigger a high_theshold
        low_threshold_ratio: ratio of the max of the signal to trigger a low_threshold
    Output:
        interrupt_t: list of times when the signal goes high
        thresholds: tuple of the high and low sthresholds
    """
def find_intterupts(
    envelope: list[float], high_theshold_ratio: float = 0.5, low_threshold_ratio: float = 0.35
) -> tuple[list[int], tuple[float, float]] {
    high_theshold = max(envelope) * high_theshold_ratio;
    low_threshold = max(envelope) * low_threshold_ratio;
    flag = False;
    interrupt_t = [];
    for x in range(len(envelope)) {
        if envelope[x] < low_threshold and flag {
            flag = False;
        } elif envelope[x] > high_theshold and not flag {
            interrupt_t.append(x);
            flag = True;
        }
    }
    return (interrupt_t, (high_theshold, low_threshold));
}

"""
    Return the number of ways that `k` stairs can be climbed
    given that you can climb either 1 or 2 stairs at a time
    """
def climb_stairs(k: int) -> int {
    num_ways = [1];
    for idx in range(1, k + 1) {
        one_step = num_ways[idx - 1];
        two_step = num_ways[idx - 2] if idx > 1 else 0;
        num_ways.append(one_step + two_step);
    }
    return num_ways[-1];
}

