"""Return % identity for two sequences."""
def compute_percent_id(seq_1: str, seq_2: str) -> int | float {
    assert len(seq_1) == len(seq_2);
    matches = sum(
        [
            1
            for i in range(len(seq_1))
            if seq_1[i] == seq_2[i]
            and seq_1[i] != "N"
            and seq_2[i] != "N"
            and seq_1[i] != "-"
            and seq_2[i] != "-"
        ]
    );
    length = len(seq_1.replace("N", "").replace("-", ""));
    pid = matches * 100 / length if length != 0 else 0;
    return pid;
}

"""Recursively merge elements of argument b into argument a.

    Primarly used for merging two dictionaries together, where dict b takes
    precedence over dict a. If 2 lists are provided, they are concatenated.
    """
def merge_map(
    a: list | dict | int | float | str | bool | None,
    b: list | dict | int | float | str | bool | None
) -> list | dict | int | float | str | bool | None {
    if isinstance(a, list) and isinstance(b, list) {
        return a + b;
    }
    if not isinstance(a, dict) or not isinstance(b, dict) {
        return b;
    }
    for key in b.keys() {
        a[key] = merge_map(a[key], b[key]) if key in a else b[key];
    }
    return a;
}

"""
    Update a lambda value according to its schedule configuration.
    """
def update_lambda_value(config: list[tuple[float, float]], n_iter: float) -> float {
    ranges = [
        i
        for i in range(len(config) - 1)
        if config[i][0] <= n_iter < config[i + 1][0]
    ];
    if len(ranges) == 0 {
        assert n_iter >= config[-1][0];
        return config[-1][1];
    }
    assert len(ranges) == 1;
    i = ranges[0];
    (x_a, y_a) = config[i];
    (x_b, y_b) = config[i + 1];
    return y_a + (n_iter - x_a) * float(y_b - y_a) / float(x_b - x_a);
}

