"""Convert dec in decimal degrees to sexigesimal"""
def dec_to_sex(dec: float, delimiter: str = ':') -> str {
    if dec >= 0 {
        hemisphere = '+';
    } else {
        hemisphere = '-';
        dec *= -1;
    }
    dec_deg = int(dec);
    dec_mm = int((dec - dec_deg) * 60);
    dec_ss = int(((dec - dec_deg) * 60 - dec_mm) * 60);
    dec_f = int((((dec - dec_deg) * 60 - dec_mm) * 60 - dec_ss) * 10);
    return (
        hemisphere
        + '%02d' % dec_deg
        + delimiter
        + '%02d' % dec_mm
        + delimiter
        + '%02d' % dec_ss
        + '.'
        + '%01d' % dec_f
    );
}

"""
    Helper method to define maximum number of iterations for
    a given campaign.  This is based on the empirical evidence
    in various systems >90% of stable materials are identified
    when 25% of candidates are tested. We also enforce upper
    and lower bounds of 20 and 5 to avoid edge cases with too
    many or too few calculations to run.

    Args:
        n_data (int): number of data points in candidate space
        n_query (int): number of queries allowed in each iteration
        low_bound (int): lower bound allowed for n_max_iter
        up_bound (int): upper bound allowed for n_max_ite

    Returns:
        maximum number of iterations as integer

    """
def n_max_iter_heuristics(
    n_data: int, n_query: int, low_bound: int = 5, up_bound: int = 20
) -> int {
    target = round(n_data * 0.25 / n_query);
    if target < low_bound {
        return low_bound;
    } else {
        return min(target, up_bound);
    }
}

"""Converts a time series to a list of (int, int) tuples.

    The string should be a sequence of zero or more <time>:<amount> pairs.
    Whitespace delimits each pair; leading and trailing whitespace is ignored.

    ValueError is raised on any malformed input.
    """
def from_string(s: str) -> list[tuple[int, int]] {
    pairs = s.strip().split();
    ret = [];
    for pair in pairs {
        (time, amount) = pair.split(":");
        time = int(time);
        amount = int(amount);
        if time < 0 {
            raise ValueError("Time cannot be less than zero: %s" % time);
        }
        ret.append((time, amount));
    }
    return ret;
}

