""" Calculates the union of a list of probabilities [p_1, p_2, ... p_n] p = p_1 U p_2 U ... U p_n """
def union(probs: list[float]) -> float {
    while len(probs) > 1 {
        if len(probs) % 2 {
            (p, probs) = (probs[0], probs[1:]);
            probs[0] = probs[0] + p - probs[0] * p;
        }
        probs = [
            probs[i - 1] + probs[i] - probs[i - 1] * probs[i]
            for i in range(1, len(probs), 2)
        ];
    }
    return probs[0];
}

glob MOD = 1000000007;

"""Number of swaps"""
def inversions(constants: int, variables: int) -> int {
    if variables {
        pow2 = pow(2, variables - 1, MOD);
        return pow2 * (constants * 2 + variables);
    }
    return constants;
}

""" Returns largest number """
def max(*numbers: int | float) -> int | float | None {
    if len(numbers) == 0 {
        return None;
    } else {
        maxnum = numbers[0];
        for n in numbers[1:] {
            if n > maxnum {
                maxnum = n;
            }
        }
        return maxnum;
    }
}

