}

"""
Compute the adjusted Rand index from pair counts; helper function.

Arguments:
a: number of pairs of elements that are clustered in both partitions
b: number of pairs of elements that are clustered in first but not second partition
c: number of pairs of elements that are clustered in second but not first partition
d: number of pairs of elements that are clustered in neither partiition

Example usage:
In [1]: a = 1
In [2]: b = 2
In [3]: c = 2
In [4]: d = 10
In [5]: adjusted_rand_index_pair_counts(a, b, c, d)
Out[5]: 0.16666666666666666
"""
def adjusted_rand_index_pair_counts(a: int, b: int, c: int, d: int) -> float {
    if a * (b + c + 2 * d) + b * (b + d) + c * (c + d) != 0 {
        return float(2 * (a * d - b * c)) / float(a * (b + c + 2 * d) + b * (b + d) + c * (c + d));
    } else {
        return 1.0;
    }
}

"""
Maps route list, which includes job ids to route location list.

:param vehicle_location: Vehicle location index.
:param route: Job ids in route.
:param jobs: Jobs information, which includes job ids, location indexes and delivery.
:return: Route location list including job location indexes.
"""
def map_route_to_route_locations(
    vehicle_location: int, route: list[int], jobs: dict[int, list[int]]
) -> list[int] {
    route_locations = [vehicle_location];
    for job in route {
        job_location = jobs[job][0];
        route_locations.append(job_location);
    }
    return route_locations;
}

