"""Returns next page of a list.

Its needed for pagination.

:param page_list: A list of available page numbers.
:param page: Page to get next page from.
:type page_list: list
:type page: int
:return: Page number of next page.
:rtype: int
"""
def next_page(page_list: list[int], page: int) -> int | None {
    if page not in page_list {
        return None;
    }
    if page_list.index(page) == len(page_list) - 1 {
        return None;
    }
    return page_list[page_list.index(page) + 1];
}

"""Make the list of verbs into present participles

E.g.:

    empower -> empowering
    drive -> driving
"""
def make_present_participles(verbs: list[str]) -> list[str] {
    res = [];
    for verb in verbs {
        parts = verb.split();
        if parts[0].endswith("e") {
            parts[0] = parts[0][:-1] + "ing";
        } else {
            parts[0] = parts[0] + "ing";
        }
        res.append(" ".join(parts));
    }
    return res;
}

