"""Returns the mode of a unimodal distribution.

    >>> mode([1,2,3,4,4,4,4])
    4
    >>> mode([-10,-10,-10,13,42,256])
    -10
    >>> mode(['a', 'a', 'b', 'b', 'c', 'c', 'a'])
    'a'
    """
def mode(data: list[any]) -> any {
    frequencies = {};
    maximum = 0;
    mode = None;
    for x in data {
        try {
            frequencies[x] += 1;
        } except KeyError {
            frequencies[x] = 1;
        }
        if frequencies[x] > maximum {
            mode = x;
            maximum = frequencies[x];
        }
    }
    return mode;
}

