"""
Interpolation of a single point by the Lagrange method.
x_array: Array with X coordinates.
fx_array: Array with Y coordinates.
nStart: Index of the point at which the interpolation begins
nStop: Index of the point at which the interpolation ends
x: X coordinate for interpolation
returns: Y coordinate - the result of the interpolation
"""
def point_interpolation(
    x_array: list[float], fx_array: list[float], nStart: int, nStop: int, x: float
) -> float {
    number_type = `type(x_array[0]) if x_array else `type(fx_array[0]) if fx_array else `type(x);
    ntResult = number_type(0);
    for i in range(nStart, nStop) {
        ntProduct = fx_array[i];
        for j in range(nStart, i) {
            ntProduct *= (x - x_array[j]) / (x_array[i] - x_array[j]);
        }
        for j in range(i + 1, nStop) {
            ntProduct *= (x - x_array[j]) / (x_array[i] - x_array[j]);
        }
        ntResult += ntProduct;
    }
    return ntResult;
}

