"""Blending function increasing concave.

    d = delta x = xabs - xdr
    u = uncertainty radius of xabs estimate error
    s = tuning scale factor

    eq 3.12

    returns blend
    """
def blendConcaveInc(d: float = 0.0, u: float = 1.0, s: float = 1.0, h: float = 1.0) -> float {
    d = float(d);
    u = float(u);
    s = float(s);
    m = 2 * s - u - d;
    if m == 0 {
        return h;
    }
    if d >= s {
        return h;
    } else {
        b = h * (s - u) / m;
    }
    return b;
}

"""Calculates the lande g factor given L, S and J.

    Reference: Sobel'man, I.I. Introduction to the
    Theory of Atomic Spectra. 1972. pp. 277
    """
def lande_g(L: float, S: float, J: float) -> float {
    return 1.0 + (J * (J + 1.0) + S * (S + 1.0) - L * (L + 1.0)) / (2.0 * J * (J + 1.0));
}

