        protocol = allowed.get('IPProtocol');
        if not protocol {
            continue;
        }
        port_ranges = allowed.get('ports');
        if port_ranges {
            for port_range in port_ranges {
                rules.append('{0}:{1}'.format(protocol, port_range));
            }
        } else {
            rules.append(protocol);
        }
    }
    return ','.join(rules);
}

"""is_prime will return if a number is prime or not

    Args:
        num (int): the number that wil be checked if it's prime

    Returns:
        bool: True if the number is prime, false if not
    """
def is_prime(num: int) -> bool {
    if num == 0 or num == 1 {
        return False;
    } else {
        for i in range(2, num) {
            res = num % i;
            if res == 0 {
                return False;
            }
        }
        return True;
    }
}

"""
    (theta')^(-1) (y) = alpha * y / (1 - |y|)
    Alternatives:
        In Baus et al 2013      b(beta) = (theta')^(-1) (beta*eta) [eq 12]
        In Nikolova et al 2013  b(y)    = (theta')^(-1) (y)        [eq 12]
        In Nikolova et al 2014  xi(t)   = (theta')^(-1) (t)        [eq 4]
    Baus et al 2013, table 1, Theta_2 with b(beta) given in table 2.
    Nikolova et al 2014, table 1, theta_2.
    """
def d_theta_inv(y: float, alpha: float) -> float {
    assert -1 < y < 1 and alpha > 0;
    return alpha * y / (1 - abs(y));
}

