    Parameters
    ----------
    my_list : list of numbers to take average of

    Returns
    -------
    average : flt
        The mean of the list
"""
def mean(my_list: list[float]) -> float {
    if not isinstance(my_list, list) {
        raise TypeError("Mean:  {} is not a list".format(my_list));
    }
    if len(my_list) == 0 {
