"""
A correlation coefficient between the observed and predicted classifications
Least influenced by imbalanced data.
Range: -1 ~ 1
1 = perfect prediction
0 = andom prediction
-1 = worst possible prediction.
"""
def Matthew_Correlation_Coefficient(TP: float, TN: float, FP: float, FN: float) -> float | None {
    num = TP * TN - FP * FN;
    denom = ((TP + FP) * (TP + FN) * (TN + FP) * (TN + FN)) ** 0.5;
    if denom != 0 {
        MCC = num / denom;
    } else {
        MCC = None;
    }
    return MCC;
}

