"""Improved version, stop when no swap occur."""
def bubbleSort2(nums: list[int]) -> list[int] {
    res = list(nums);
    flag = True;
    while flag {
        flag = False;
        for j in range(1, len(res)) {
            if res[j - 1] > res[j] {
                (res[j - 1], res[j]) = (res[j], res[j - 1]);
                flag = True;
            }
        }
    }
    return res;
}

"""Miller-Rabin test with base a.

Args:
    n (int): number to test
    a (int): base

Returns:
    bool: result
"""
def _MillerRabin(n: int, a: int) -> bool {
    d = n - 1;
    while (d & 1) == 0 {
        d >>= 1;
    }
    t = pow(a, d, n);
    while d != n - 1 and t != n - 1 and t != 1 {
        t = (t * t) % n;
        d <<= 1;
    }
    return t == n - 1 or (d & 1) == 1;
}

"""Calculate the mean of the posterior probability density for non-informative priors.

The probability that the stimulus displays value j on dimension i given that it
comes from category k (equation 3-7 in Anderson 1990).
"""
def probability_of_ij_given_k(
    i: int, j: int, k: int, category_membership_list: list[list[int]], stimuli: list[list[int]], m: list[int]
) -> float {
    nk = len(category_membership_list[k]);
    denominator = nk + m[i];
    count = 0;
    for idx in range(len(category_membership_list[k])) {
        if stimuli[category_membership_list[k][idx]][i] == j {
            count += 1;
        }
    }
    numerator = count + 1;
    return numerator / denominator;
}

