def verify_command(command: list[str]) -> tuple[str | bool, str | None] {
    command_length = len(command);
    if command_length > 0 {
        if command_length == 1 {
            if command[0] in ["Q", "t"] {
                return (command[0], None);
            }
        }
        if command_length == 2 {
            if (
                (command[0] == 'S' and command[1] in ["r", "i", "m"])
                or (command[0] in ["A", "AR", "d", "D"] and command[1].isnumeric())
            ) {
                return (command[0], command[1]);
            }
        }
    }
    return (False, " ".join(command));
}

"""
        Profile
        Forms sorted dictionary with
        probabilities values for every character
    """
def form_frequency_dict(data: str) -> dict[str, float] {
    laters = {};
    for char in data {
        if char in laters {
            laters[char] += 1;
        } else {
            laters.update({char: 1});
        }
    }
    for later in laters {
        laters[later] = laters[later] / len(data) * 100;
    }
    items = laters.items();
    laters = {
        k: v
        for (k, v) in sorted(items, key=lambda item: dict[str, float] { item[1]; }, reverse=True)
    };
    return laters;
