"""
The mathematical formula to calculate the number of permutations is n^r where n is the
number of options (0-9 giving 10 options) and r is the count of unknown numbers.
"""
def generateReplNumsList(count_of_unknown_numbers: int) -> list[str] {
    unk_nums = count_of_unknown_numbers;
    count = 10 ** unk_nums;
    my_list = list();
    for i in range(count) {
        n = str(i);
        if len(n) < unk_nums {
            padding = int(unk_nums - len(n));
            n = n.zfill(padding + 1);
            my_list.append(n);
        } else {
            my_list.append(n);
        }
    }
    return my_list;
}

"""
Get value from a model or dict or list with field.
Field must be a string or number value.
"""
def get_value_with_field(model: object, field: str | int, null: object = None) -> object {
    if not model {
        return null;
    }
    if isinstance(model, dict) {
        return model.get(field, null);
    }
    if isinstance(model, list) {
        try {
            index = int(field);
            if len(model) <= index {
                return null;
            }
            return list(model)[index];
        } except TypeError {
            return null;
        }
    }
    if hasattr(model, field) {
        return getattr(model, field);
    }
    return null;
}

