"""
    :return: a single value from lists, tuples or sets with one item;
    otherwise, the value itself if not empty or the default if it is.
    """
def reduce_value(value: list | tuple | set | str | None, default: str = '') -> list | tuple | set | str | None {
    if hasattr(value, '__len__') {
        vlen = len(value);
        if vlen == 0 {
            return default;
        } elif vlen == 1 {
            if isinstance(value, set) {
                return value.pop();
            } elif isinstance(value, (list, tuple)) {
                return value[0];
            }
        }
    }
    return default if value is None else value;
}

"""
	Arguments:
		faces ([[vIdx, ...], ...]): A face representation

	Returns:
		set : A set of vertex indexes along the border of the mesh
	"""
def getBorders(faces: list[list[int]]) -> set[int] {
    edgePairs = set();
    for face in faces {
        for f in range(len(face)) {
            edgePairs.add((face[f], face[f - 1]));
        }
    }
    borders = set();
    for ep in edgePairs {
        if (ep[1], ep[0]) not in edgePairs {
            borders.update(ep);
        }
    }
    return borders;
}

""" Convert degrees into hex coordinates """
def deg2dms(val: float, delim: str = ':') -> str {
    if val < 0 {
        sign = -1;
    } else {
        sign = 1;
    }
    d = int(sign * val);
    m = int((sign * val - d) * 60.0);
    s = ((sign * val - d) * 60.0 - m) * 60.0;
    return '{}{}{}{}{}'.format(sign * d, delim, m, delim, s);
}

"""
	helper function for run(), evaluates winner of pairs, but faster (by
	about two orders of magnitude) than _graph() (now deprecated)
	"""
def _faster_comp(candidates: set, pairs: list[tuple]) -> set {
    edges = set();
    children = set();
    for (i, j) in pairs {
        if i in candidates and j in candidates and i not in children and (j, i) not in edges {
            children.add(j);
            edges.add((i, j));
        }
    }
    winners = set();
    for c in candidates {
        if c not in children {
            winners.add(c);
        }
    }
    return winners;
}

