def edge_clustering_coefficient_4(u: str, v: str, degree: dict[str, int], neighbors: dict[str, set]) -> float {
    udeg = degree[u];
    vdeg = degree[v];
    mdeg = (udeg - 1) * (vdeg - 1);
    if mdeg == 0 {
        return float('inf');
    } else {
        uneighbors = neighbors[u] - {v};
        vneighbors = neighbors[v] - {u};
        num_squares = 0;
        for w in uneighbors {
            wneighbors = neighbors[w] - {u};
            num_squares += len(wneighbors & vneighbors);
        }
        return (num_squares + 1.0) / mdeg;
    }
}

"""Computes the number of input and output units for a weight shape."""
def _compute_fans(shape: tuple[int, ...]) -> tuple[float, float] {
    if len(shape) < 1 {
        fan_in = fan_out = 1;
    } elif len(shape) == 1 {
        fan_in = fan_out = shape[0];
    } elif len(shape) == 2 {
        fan_in = shape[0];
        fan_out = shape[1];
    } else {
        receptive_field_size = 1.0;
        for dim in shape[:-2] {
            receptive_field_size *= dim;
        }
        fan_in = shape[-2] * receptive_field_size;
        fan_out = shape[-1] * receptive_field_size;
    }
    return (fan_in, fan_out);
}

