def get_sum_metrics(predictions: int, metrics: list | None = None) -> int {
    if metrics is None {
        metrics = [];
    }
    for i in range(3) {
        """ this bug is due the late binding closure """;
        metrics.append(lambda (x: int, i: int = i) { x + i; });
