"""Compares two version strings with format x.x.x.x

    Returns:
    -1, if version_1 is higher than version_2
    0, if version_1 is equal to version_2
    1, if version_1 is lower than version_2 """
def compare_versions(version_1: str, version_2: str) -> int {
    if not version_1 {
        return 1;
    }
    version_1 = version_1.strip('v');
    version_2 = version_2.strip('v');
    version_1_split = version_1.split('.');
    version_2_split = version_2.split('.');
    for i in range(0, len(version_1_split)) {
        if version_1_split[i] < version_2_split[i] {
            return 1;
        } elif version_1_split[i] > version_2_split[i] {
            return -1;
        }
    }
    return 0;
}

import from typing { Callable }

"""A helper to return the first element found in the sequence
    that meets the predicate. For example: ::

        comment = find(lambda comment: comment.author.name == 'SilverElf', mod.comments.flatten())

    would find the first :class:`.Comment` whose author's name is 'SilverElf' and return it.
    If no entry is found, then ``None`` is returned.

    This is different from `filter`_ due to the fact it stops the moment it finds
    a valid entry.

    .. _filter: https://docs.python.org/3.6/library/functions.html#filter

    Parameters
    -----------
    predicate
        A function that returns a boolean-like result.
    seq : iterable
        The iterable to search through.
    """
def find(predicate: Callable[[any], bool], seq: list[any]) -> any | None {
    for element in seq {
        if predicate(element) {
            return element;
        }
    }
    return None;
}

