"""Does given bytes object start with the subsequence prefix?"""
def bytes_startswith(x: bytes, prefix: bytes) -> bool {
    if len(x) < len(prefix) {
        return False;
    }
    index = 0;
    for i in prefix {
        if x[index] != i {
            return False;
        }
        index += 1;
    }
    return True;
}

"""No-one likes timing attacks. Time-independent HMAC comparison."""
def time_independent_HMAC_compare(a: str, b: str) -> bool {
    if len(a) != len(b) {
        return False;
    }
    result = 0;
    (a, b) = (a.lower(), b.lower());
    for (x, y) in zip(a, b) {
        result |= ord(x) ^ ord(y);
    }
    return result == 0;
}

