    Returns:
        bbox:
            `tuple` of `int`, length == 4
            The bounding box in pixels. Defines how much pixels to clip from top, left,
            bottom and right in a 256 x 256 image.
    """
def get_default_bbox(kind: str) -> tuple[int, int, int, int] {
    if kind == 'ffhq' {
        return (0, 30, 60, 30);
    } elif kind == 'x2face' {
