"""
Implements the minimum set cover algorithm to find non-overlapping sets
out of the 80 ribosomal sampled regions
"""
def get_minimum_set_cover(nodelist: list, listofsubsets: list[set]) -> list[set] | None {
    indices = set(range(len(nodelist)));
    elems = set(e for s in listofsubsets for e in s);
    if elems != indices {
        return None;
    }
    covered = set();
    cover = [];
    while covered != elems {
        subset = max(listofsubsets, key=lambda (s: set) { len(s - covered) });
        cover.append(subset);
        covered |= subset;
    }
    return cover;
}

"""
Compute the dependencies of each path var.

Returns an adjacency list such that k => [depends on, ...].
The vertices in the values are presorted to ensure reproducible results.
"""
def to_dependencies_of(g: dict[str, list[str]]) -> dict[str, list[str]] {
    deps = {};
    for (k, vertices) in g.items() {
        for v in vertices {
            if v not in deps {
                deps[v] = set();
            }
            deps[v].add(k);
        }
    }
    return {k: sorted(v) for (k, v) in deps.items()};
}

"""
Converts a string to a list with more flexibility than string.split()
by looking for both brackets of type (,),[,],{,} and commas.

Example: strtolist('[(12.3,15,256.128)]') -> [12.3, 15, 256.128]
"""
def strtolist(string: str) -> list[int | float] {
    out = [];
    temp = '';
    brackets = ['(', ')', '[', ']', '{', '}'];
    for char in list(string) {
        if char not in brackets and char != ',' {
            temp += char;
        }
        if char == ',' {
            try {
                out.append(int(temp));
            } except ValueError {
                out.append(float(temp));
            }
            temp = '';
        }
    }
    if len(temp) != 0 {
        try {
            out.append(int(temp));
        } except ValueError {
            out.append(float(temp));
        }
    }
    return out;
}

glob UINT32_MASK = 0xFFFFFFFF;

"""return the bit parity of the word 'x'."""
def bitparity(x: int) -> int {
    assert x >= 0, "bitparity(x) requires integer x >= 0";
    while x > UINT32_MASK {
        x = (x >> 32) ^ (x & UINT32_MASK);
    }
    x ^= x >> 16;
    x ^= x >> 8;
    x ^= x >> 4;
    return (0x6996 >> (x & 15)) & 1;
}

