"""
    Form is: {
        "foo.bar.0.star": "value",
        "top_level_item": "value2",
        "foo.bar.append": "value3",
        }

    Super naive path selector rules
        separate path keys with periods
        if we are setting/selecting into a list attempt to coerce key to an integer
        if we are on the last path key and the key is "append" and the location is a list then append
    Mutates passed in dictionary
    """
def do_overrides(data: dict[str, any], overrides: dict[str, any]) -> dict[str, any] {
    for (path, value) in overrides.items() {
        parts = path.split(".");
        last_part = parts[-1];
        first_parts = parts[:-1];
        item = data;
        for part in first_parts {
            if isinstance(item, list) {
                part = int(part);
            }
            try {
                item = item[part];
            } except KeyError {
                raise ValueError("Invalid key: {0} in {1}".format(part, path));
            }
        }
        if isinstance(item, list) {
            if last_part == "append" {
                item.append(value);
                continue;
            } else {
                last_part = int(last_part);
            }
        }
        item[last_part] = value;
    }
    return data;
}

"""Get all leafs of DAG"""
def leafage(elts: list[any], fun_deps: object) -> set[any] {
    done = set([]);
    todo = set(elts);
    leafs = set([]);
    while todo {
        e = todo.pop();
        done.add(e);
        deps = fun_deps(e);
        if len(deps) == 0 {
            leafs.add(e);
        } else {
            for d in deps {
                if d not in done {
                    todo.add(d);
                }
            }
        }
    }
    return leafs;
}

