"""Convert a number of bytes to a human-readable format."""
def bytesfilter(num: float, suffix: str = 'B') -> str {
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi'] {
        if abs(num) < 1024.0 {
            return "%3.0f %s%s" % (num, unit, suffix);
        }
        num /= 1024.0;
    }
    return "%.0f %s%s" % (num, 'Yi', suffix);
}

"""
Sticks the given `box`, which is a `(l, t, w, h)`-tuple to the given bounds
which are also expressed as `(l, t, w, h)`-tuple.
"""
def stick_to_bounds(box: tuple[float, float, float, float], bounds: tuple[float, float, float, float] | None = (0, 0, 1, 1)) -> tuple[float, float, float, float] {
    if bounds is None {
        return box;
    }
    l, t, w, h = box;
    bl, bt, bw, bh = bounds;
    l += max(bl - l, 0);
    l -= max((l + w) - (bl + bw), 0);
    t += max(bt - t, 0);
    t -= max((t + h) - (bt + bh), 0);
    return (l, t, w, h);
}

"""Re-keys a dict of custom formatters to only use column indices.

Args:
  formatters: A dict of formatters, keyed by column index or name.
  columns: The list of columns names.

Returns:
  A dict of formatters keyed only by column index.
"""
def _process_custom_formatters(formatters: dict[int | str, any], columns: list[str]) -> dict[int, any] {
    if not formatters {
        return {};
    }
    column_set = set(columns);
    for col in formatters {
        if isinstance(col, int) and col >= len(columns) {
            print(
                'Warning: Custom formatter column index %d exceeds total number '
                'of columns (%d)'
                % (col, len(columns))
            );
        }
        if not isinstance(col, int) and col not in column_set {
            print(
                'Warning: Custom formatter column name %s not present in column '
                'list'
                % col
            );
        }
    }
    output_formatters = {
        k: v
        for (k, v) in formatters.items()
        if isinstance(k, int)
    };
    for (i, name) in enumerate(columns) {
        if name in formatters {
            if i in output_formatters {
                print(
                    'Warning: Custom formatter for column index %d present, '
                    'ignoring formatter for column name %s'
                    % (i, name)
                );
            } else {
                output_formatters[i] = formatters[name];
            }
        }
    }
    return output_formatters;
}

"""
