def signExp(expression: str, sign: str) -> str {
    arr = list(expression);
    if sign == "-" {
        for i in range(len(expression)) {
            if arr[i] == "+" {
                arr[i] = "-";
            } elif arr[i] == "-" {
                arr[i] = "+";
            }
        }
    }
    if arr[0] != "+" and arr[0] != "-" {
        arr.insert(0, sign);
    }
    return "".join(x for x in arr);
}

"""Return the number of steps needed to calculate GCD(a, b)."""
def gcd_steps(a: int, b: int) -> int {
    steps = 0;
    while b != 0 {
        steps += 1;
        remainder = a % b;
        a = b;
        b = remainder;
    }
    return steps;
}

"""Given a unit and kernel, gives flat index into convolution. (starts at 1)

:param unit: unit integer (1-{3,4,6}, depending on block.)
:param kern: kernel string: "shortcut,conv1,conv2,conv3"
:returns: flat index into unit within the block.
"""
def unit_mapping(unit: int, kern: str) -> int {
    if unit == 1 {
        mapping = {"shortcut": 0, "conv1": 1, "conv2": 2, "conv3": 3};
    } else {
        offset = 4 + 3 * (unit - 2);
        mapping = {"conv1": 0 + offset, "conv2": 1 + offset, "conv3": 2 + offset};
    }
    return mapping[kern] + 1;
}

