"""
Convert degrees, minutes, seconds, quadrant to decimal degrees

:param degrees: coordinate degrees
:param minutes: coordinate minutes
:param seconds: coordinate seconds
:param quadrant: coordinate quadrant (N, E, S, W)

:return: decimal degrees
"""
def dms2dd(degrees: int | str, minutes: int | str, seconds: int | str, quadrant: str) -> float {
    illegal_vals = (None, '', '');
    for iv in illegal_vals {
        if iv in (degrees, minutes, seconds, quadrant) {
            raise ValueError("ERROR: Illegal value: %s" % iv);
        }
    }
    if quadrant.lower() not in ('n', 'e', 's', 'w') {
        raise ValueError("ERROR: Invalid quadrant: %s" % quadrant);
    }
    output = int(degrees) + int(minutes) / 60 + int(seconds) / 3600;
    if quadrant.lower() in ('s', 'w') {
        output *= -1;
    }
    return output;
}

"""Convert testkit parameter format to driver (python) parameter."""
def to_param(m: dict[str, object]) -> None | str | bool | int | float | bytearray | list | dict {
    value = m["data"]["value"];
    name = m["name"];
    if name == "CypherNull" {
        return None;
    }
    if name == "CypherString" {
        return str(value);
    }
    if name == "CypherBool" {
        return bool(value);
    }
    if name == "CypherInt" {
        return int(value);
    }
    if name == "CypherFloat" {
        return float(value);
    }
    if name == "CypherString" {
        return str(value);
    }
    if name == "CypherBytes" {
        return bytearray([int(byte, 16) for byte in value.split()]);
    }
    if name == "CypherList" {
        return [to_param(v) for v in value];
    }
    if name == "CypherMap" {
        return {k: to_param(value[k]) for k in value};
    }
    raise Exception("Unknown param type " + name);
}

