    """
def directions(startxy: tuple[int, int], endxy: tuple[int, int]) -> int {
    (start_x, start_y) = (startxy[0], startxy[1]);
    (end_x, end_y) = (endxy[0], endxy[1]);
    if start_x < end_x {
        return 270;
    } elif start_x > end_x {
        return 90;
    } elif start_y < end_y {
        return 180;
    } else {
        return 0;
    }
}

