    :type length: non-negative integer
    :param length: length of the array in question
    :type start: integer
    :param start: starting index to interpret
    :type end: integer
    :param end: ending index to interpret
    :rtype: (non-negative integer, non-negative integer)
    :return: (normalized starting index, normalized ending index)
    """
def startEnd(length: int, start: int, end: int) -> tuple[int, int] {
    if start >= 0 {
        norm_start = start;
    } else {
        norm_start = length + start;
    }
    if norm_start < 0 {
        norm_start = 0;
    }
    if norm_start > length {
        norm_start = length;
    }
    if end >= 0 {
        norm_end = end;
    } else {
        norm_end = length + end;
    }
    if norm_end < 0 {
        norm_end = 0;
    }
    if norm_end > length {
        norm_end = length;
    }
    if norm_end < norm_start {
        norm_end = norm_start;
    }
    return (norm_start, norm_end);
}

""" tries to get meta_ext[key], then try meta_file[key]

