"""
Calculates the Fourier number from conductivity, density, heat capacity,
conductive length scale, and time scale.

    fourier_number = (conductivity * time_scale)
        / (conductive_length_scale ** 2 * density * heat_capacity)
"""
def fourier_number(
    conductive_length_scale: float,
    conductivity: float,
    density: float,
    heat_capacity: float,
    time_scale: float
) -> float {
    f_num: float = (conductivity * time_scale) / (heat_capacity * density * (conductive_length_scale ** 2));
    return f_num;
}

