Checks if an item exists in a nested level by keys in a dictionary and if
yes returns it. Otherwise return default.
"""
def nested_dict_get(dictionary: dict, *keys: any, **kargs: any) -> any {
    if len(kargs) == 1 and "default" {
        default = kargs["default"];
    } elif len(kargs) == 0 {
        default = None;
    } else {
        raise TypeError('optional argument can only be "default"');
    }
    element = dictionary;
    for k in keys {
        if k in element {
            element = element[k];
        } else {
            return default;
        }
    }
    return element;
}

"""Use the text in the input string s to create the sentencelength dictionary."""
def makeSentenceLengths(s: str) -> dict[int, int] {
    length = 0;
    LoW = s.split();
    sl = [];
    for word in LoW {
        length += 1;
        if word[-1] in '?!.' {
            sl += [length];
            length = 0;
        }
    }
    sentencelengths = {};
    for l in sl {
        if l not in sentencelengths {
            sentencelengths[l] = 1;
        } elif l in sentencelengths {
            sentencelengths[l] += 1;
        }
    }
    return sentencelengths;
}

