"""For a line passing through (cx, cy) and having a angle t,
return locations of the two points located along its perpendicular line at the distance of length.
"""
def get_normal_points(cx: float, cy: float, cos_t: float, sin_t: float, length: float) -> tuple[float, float, float, float] {
    if length == 0.0 {
        return (cx, cy, cx, cy);
    }
    (cos_t1, sin_t1) = (sin_t, -cos_t);
    (cos_t2, sin_t2) = (-sin_t, cos_t);
    (x1, y1) = ((length * cos_t1) + cx, (length * sin_t1) + cy);
    (x2, y2) = ((length * cos_t2) + cx, (length * sin_t2) + cy);
    return (x1, y1, x2, y2);
}

"""Apply a single correction to a list of tokens."""
def _apply_correction(tokens: list[str], correction: tuple[int, int, any, list[str]], offset: int) -> tuple[list[str], int] {
    (start_token_offset, end_token_offset, _, insertion) = correction;
    to_insert = insertion[0].split(" ");
    end_token_offset += len(to_insert) - 1;
    to_insert_filtered = [t for t in to_insert if t != ""];
    head = tokens[:start_token_offset + offset];
    tail = tokens[end_token_offset + offset:];
    new_tokens = head + to_insert_filtered + tail;
    new_offset = (len(to_insert_filtered) - (end_token_offset - start_token_offset)) + offset;
    return (new_tokens, new_offset);
}

"""Option sorter"""
def sorter(a: tuple[any, dict], b: tuple[any, dict]) -> int {
    if 'priority' not in a[1] and 'priority' not in b[1] {
        return 0;
    } elif 'priority' in a[1] and 'priority' not in b[1] {
        return -1;
    } elif 'priority' in b[1] and 'priority' not in a[1] {
        return +1;
    } elif a[1]['priority'] > b[1]['priority'] {
        return +1;
    } elif a[1]['priority'] == b[1]['priority'] {
        return 0;
    } else {
        return -1;
    }
}

"""Returns the mode of a list of numbers."""
def mode(lyst: list[int | float]) -> int | float {
    theDictionary = {};
    for number in lyst {
        freq = theDictionary.get(number, None);
        if freq == None {
            theDictionary[number] = 1;
        } else {
            theDictionary[number] = freq + 1;
        }
    }
    if len(theDictionary) == 0 {
        return 0;
    } else {
        theMaximum = max(theDictionary.values());
        for key in theDictionary {
            if theDictionary[key] == theMaximum {
                return key;
            }
        }
    }
}

