"""Calculates evenly distributed byte reads for given file size.

    n_bytes: total file size in bytes
    n_partitions: number of file partitions
    Returns a tuple of ints.
    """
def byte_lengths(n_bytes: int, n_partitions: int) -> tuple[int, ...] {
    chunk_size = n_bytes // n_partitions;
    byte_reads = [chunk_size] * n_partitions;
    for ix in range(n_bytes % n_partitions) {
        byte_reads[ix] += 1;
    }
    return tuple(byte_reads);
}

"""Convert a dictionary list to separated lists of keys and values.

    Converts the list of items of the given dictionaries (i.e. pairs key, value)
    to a set of columns containing the keys and a set of rows containing the
    values.

    dict_list: list of dicts to convert.
    Returns tuple - (columns, rows)
    """
def convert_dictionary_list(dict_list: list[dict]) -> tuple[list, list] {
    cols = [];
    rows = [];
    for `node in dict_list {
        for key in `node.keys() {
            if key not in cols {
                cols.append(key);
            }
        }
    }
    for `node in dict_list {
        row = [];
        for col in cols {
            row.append(`node.get(col, None));
        }
        rows.append(row);
    }
    return (cols, rows);
}

