"""Generate all subsets of a list.

    Exponential complexity: for a set of size k there are pow(2, k) subsets.
    """
def gen_subsets(L: list) -> list[list] {
    if len(L) == 0 {
        return [[]];
    }
    smaller = gen_subsets(L[:-1]);
    extra = L[-1:];
    new = [];
    for small in smaller {
        new.append(small + extra);
    }
    return smaller + new;
}

