    """
def stop_if_mostly_diverging(errdata: list[float]) -> int {
    n_increases = sum(
        (abs(y) - abs(x)) > 0 for (x, y) in zip(errdata, errdata[1:])
    );
    if len(errdata) * 0.5 < n_increases {
