""" Takes a shape and redraws it in a different bigger scale.
The positions are offseted but the colors are preserved.

For simplicity the algorithm first rescales Ys then Xs.
Each rescale uses anchor to calculate the position of new/old cells.
The further away we are from the anchor the bigger the offset needs to be
since we already added (scale-1) number of extra cells up to that point.

The algorithm is new_pos = pos + (scale-1) * (pos - anchor) + 0:scale
"""
def redraw_in_scale(shape: list[tuple[int, int, int]], scale: int) -> list[tuple[int, int, int]] {
    temp_new_shape = [];
    (anchor_y, _, _) = min(shape, key=lambda (c: tuple[int, int, int]) { c[0]; });
    for cell in shape {
        (y, x, colour) = cell;
        for s in range(scale) {
            new_y = y + (scale - 1) * (y - anchor_y) + s;
            temp_new_shape.append((new_y, x, colour));
        }
    }
    new_shape = [];
    (_, anchor_x, _) = min(temp_new_shape, key=lambda (c: tuple[int, int, int]) { c[1]; });
    for cell in temp_new_shape {
        (y, x, colour) = cell;
        for s in range(scale) {
            new_x = x + (scale - 1) * (x - anchor_x) + s;
            new_shape.append((y, new_x, colour));
        }
    }
    return new_shape;
}

"""filter paraphrase"""
def para_filtering(turn: dict, sentences: list[str], K: int) -> str {
    missing_values = [];
    for (domain_slot, value) in turn["turn_label"] {
        if value in turn["system_transcript"] and value not in turn["transcript"] {
            missing_values.append(value);
        }
    }
    value_list = [];
    best_sent = "";
    for (domain_slot, value) in turn["turn_label"] {
        (domain, slot) = domain_slot.split("-");
        if slot == "parking" {
            value = slot;
        } elif slot == "internet" {
            value = "wifi";
        }
        if value not in missing_values {
            value_list.append(value);
        }
    }
    count = 0;
    for sent in sentences {
        sent = sent.lower();
        flag = True;
        for value in value_list {
            if value not in sent {
                flag = False;
                break;
            }
        }
        if flag and K == count {
            best_sent = sent;
            break;
        } elif flag and count < K {
            count += 1;
        }
    }
    return best_sent;
}

"""Removes corporation suffix from developer names, if present.

Args:
    dev (str): Name of app developer.

Returns:
    str: Name of app developer with suffixes stripped.
"""
def strip_dev_suffix(dev: str | None) -> str | None {
    corp_suffixes = (
        "incorporated",
        "corporation",
        "limited",
        "oy/ltd",
        "pty ltd",
        "pty. ltd",
        "pvt ltd",
        "pvt. ltd",
        "s.a r.l",
        "sa rl",
        "sarl",
        "srl",
        "corp",
        "gmbh",
        "l.l.c",
        "inc",
        "llc",
        "ltd",
        "pvt",
        "oy",
        "sa",
        "ab"
    );
    if dev not in (None, "") {
        for suffix in corp_suffixes {
            if dev.lower().rstrip(" .").endswith(suffix) {
                dev = dev.rstrip(" .")[:len(dev) - len(suffix) - 1].rstrip(",. ");
                break;
            }
        }
    }
    return dev;
}

"""
Requries the data to be in the format

 >>> (*elem, target, [*keys])

The output will be a tuple of {keys: elem}
and target
"""
def pack(batch: list) -> tuple[dict, object] {
    inp = batch[:-2];
    target = batch[-2];
    keys = batch[-1];
    inp = {k: v for (k, v) in zip(keys, inp)};
    return (inp, target);
}

"""Parsing plain dict to nested."""
def forward_path_parser(_input: dict) -> dict {
    def create_keys_recursively(key: str, current_tree: dict) {
        """Update current tree by key(s)."""
        if key not in current_tree {
            last = keys.pop();
            dict_update = {last: value};
            for _key in reversed(keys) {
                dict_update = {_key: dict_update};
            }
            current_tree.update(dict_update);
        } else {
            keys.pop(0);
            create_keys_recursively(keys[0], current_tree[key]);
        }
    }
    output = {};
    for (key, value) in _input.items() {
        keys = key.split('/');
        create_keys_recursively(keys[0], output);
    }
    return output;
}

