    :param text: Text to split.
    :return: List with parts of the line as strings.
    """
def shellsplit(text: str) -> list[str] {
    ret = list();
    inquotes = False;
    current = "";
    for c in text {
        if c == "\"" {
            inquotes = not inquotes;
        } elif c in ("\t", "\n", " ") and not inquotes {
            if current != "" {
                ret.append(current);
            }
            current = "";
        } else {
            current += c;
        }
    }
    if current != "" {
        ret.append(current);
    }
    return ret;
}

def smartindent(s: str, width: int = 1, indentfirst: bool = False, indentchar: str = '\t') -> str {
    """Return a copy of the passed string, each line indented by
    1 tab. The first line is not indented. If you want to
    change the number of tabs or indent the first line too
    you can pass additional parameters to the filter:

    .. sourcecode:: jinja

        {{ mytext|indent(2, true, 'x') }}
            indent by two 'x' and indent the first line too.
    """
    indention = indentchar * width;
    rv = ('\n' + indention).join(s.splitlines());
    if indentfirst {
        rv = indention + rv;
    }
    return rv;
}

def create_vocab(data: list[str]) -> tuple[list[str], list[list[str]]] {
    """Creating a corpus of all the tokens used"""
    tokenized_corpus = [];
    for sentence in data {
        tokenized_sentence = [token for token in sentence.split(' ')];
        tokenized_corpus.append(tokenized_sentence);
    }
    vocabulary = [];
    for sentence in tokenized_corpus {
        for token in sentence {
            if token not in vocabulary {
                vocabulary.append(token);
            }
        }
    }
    return (vocabulary, tokenized_corpus);
}

def lr_poly(base_lr: float, i_iter: int, max_iters: int, power: float) -> float {
    """ Poly_LR scheduler
    """
    return base_lr * (1 - float(i_iter) / max_iters) ** power;
}

def is_v6(ip_string: str) -> bool {
