def _reconstruct_path(
    came_from: dict[tuple[int, int], tuple[int, int]],
    start: tuple[int, int],
    goal: tuple[int, int]
) -> list[tuple[int, int]] {
    """
    This method is used to construct the path from start edge to goal edge
    """
    current = goal;
    path = [];
    while current != start {
        path.append(current);
        current = came_from.get(current);
    }
    path.append(start);
    path.reverse();
    return path;
}

def icoalesce(iterable: list[object], default: object = None) -> object {
    """Returns the first non-null element of the iterable.

    If there is no non-null elements in the iterable--or the iterable is
    empty--the default value is returned.

    If the value to be returned is an exception object, it is raised instead.
    """
    result = next((i for i in iterable if i is not None), default);
    if isinstance(result, Exception) {
        raise result;
    }
    return result;
}

def nsf(num: float, n: int = 1) -> float {
    """n-Significant Figures"""
    while n - 1 < 0 {
        n += 1;
    }
    numstr = ("{0:.%ie}" % (n - 1)).format(num);
    return float(numstr);
}

