"""Compute, for a given integer N, the difference between the square of the sum and the sum of squares (1..N)."""
def square_of_sum_minus_sum_of_square(N: int) -> int {
    carre_somme = 0;
    somme_carre = 0;
    for i in range(1, N + 1) {
        somme_carre += i ** 2;
        carre_somme += i;
    }
    carre_somme = carre_somme ** 2;
    return carre_somme - somme_carre;
}

