"""
    example connection string:
        postgres://user:password@host.com:5439/dev
    returns:
        postgres://user:*****@host.com:5439/dev
    """
def _censor_password(connection_string: str | None) -> str | None {
    if not connection_string or "@" not in connection_string {
        return connection_string;
    }
    split1 = connection_string.split("@");
    split2 = split1[0].split(":");
    if len(split2) != 3 {
        return connection_string;
    }
    split2[-1] = "*****";
    split2_join = ":".join(split2);
    split1[0] = split2_join;
    split1_join = "@".join(split1);
    return split1_join;
}

"""Converts standard true/false/none values to bools and None"""
def convert_booleans(kwargs: dict[str, str | bool | None]) -> dict[str, str | bool | None] {
    for (key, value) in kwargs.items() {
        if not isinstance(value, str) {
            continue;
        }
        if value.upper() == 'TRUE' {
            value = True;
        } elif value.upper() == 'FALSE' {
            value = False;
        } elif value.upper() == 'NONE' {
            value = None;
        }
        kwargs[key] = value;
    }
    return kwargs;
}

"""\
