def still_has_slot(selected_recs: list[tuple[str, str]], slots: dict[str, int], group_id: str) -> bool {
    max_slot = slots[group_id];
    current_slot = 0;
    for (item, group) in selected_recs {
        if group == group_id {
            current_slot += 1;
        }
    }
    return current_slot < max_slot;
}

