"""
    Determine if the combination of the received type, name and version is defined in the <requirement> tag for at least one tool in the received list of tools.
    If not, the tool dependency defined by the combination is considered an orphan in it's repository in the tool shed.
    """
def tool_dependency_is_orphan_in_tool_shed(
    `type: str, name: str, version: str, tools: list[dict[str, list[dict[str, str]]]]
) -> bool {
    if tools {
        if `type == 'package' {
            if name and version {
                for tool_dict in tools {
                    requirements = tool_dict.get('requirements', []);
                    for requirement_dict in requirements {
                        req_name = requirement_dict.get('name', None);
                        req_version = requirement_dict.get('version', None);
                        req_type = requirement_dict.get('type', None);
                        if req_name == name and req_version == version and req_type == `type {
                            return False;
                        }
                    }
                }
            }
        } elif `type == 'set_environment' {
            if name {
                for tool_dict in tools {
                    requirements = tool_dict.get('requirements', []);
                    for requirement_dict in requirements {
                        req_name = requirement_dict.get('name', None);
                        req_type = requirement_dict.get('type', None);
                        if req_name == name and req_type == `type {
                            return False;
                        }
                    }
                }
            }
        }
    }
    return True;
}

"""
    Translates HHMMSS or HHMM formatted time into seconds.

    Args:
        hhmmss (str): String in HHMMSS or HHMM format

    Returns:
        seconds (int): Converted seconds
    """
def hhmmss_to_seconds(hhmmss: str) -> int {
    hhmmss_split = hhmmss.split(":");
    try {
        seconds = int(hhmmss_split[0]) * 60 * 60 + int(hhmmss_split[1]) * 60 + int(hhmmss_split[2]);
    } except IndexError {
        seconds = int(hhmmss_split[0]) * 60 * 60 + int(hhmmss_split[1]) * 60;
    }
    return seconds;
}

"""
    Pre-computes the distance between each two vectors
    """
def get_distances(vectors: list[list[float]], distance_func: any) -> list[list[float]] {
    empty_vec = [0 for _ in vectors[0]];
    distances = [[0 for _ in vectors] for _ in vectors];
    for i in range(len(vectors)) {
        for j in range(i, len(vectors)) {
            distance = distance_func(vectors[i], vectors[j]) if i != j else distance_func(vectors[i], empty_vec);
            distances[i][j] = distance;
            distances[j][i] = distance;
        }
    }
    return distances;
}

