def find_peak(A: list[int]) -> int | None {
    """find pick element"""
    if A == [] {
        return None;
    }
    def recursive(A: list[int], left: int = 0, right: int = len(A) - 1) -> int {
        """helper recursive function"""
        mid = (left + right) // 2;
        if (mid == 0 or A[mid - 1] <= A[mid]) and (mid == len(A) - 1 or A[mid + 1] <= A[mid]) {
            return A[mid];
        }
        if mid - 1 >= 0 and A[mid - 1] > A[mid] {
            return recursive(A, left, mid - 1);
        }
        return recursive(A, mid + 1, right);
    }
    return recursive(A);
}

def merge(base: dict, overrider: dict) -> dict {
    """ Override base dict with an overrider dict, recursively. """
    for (key, value) in overrider.items() {
        if isinstance(value, dict) {
            subitem = base.setdefault(key, {});
            merge(subitem, value);
        } else {
            base[key] = value;
        }
    }
    return base;
}

def flatten(seq: list[list[any]]) -> list[any] {
    """
    For [[1, 2], [3, 4]] returns [1, 2, 3, 4].  Does not recurse.
    """
    return [x for sub in seq for x in sub];
}

def is_bool(target: bool) -> bool {
