def nested_contains(list_: list[any], value: any) -> bool {
    """Return whether list_, or any nested sub-list of list_ contains value."""
    if not isinstance(list_, list) {
        return list_ == value;
    } else {
        return any(nested_contains(item, value) for item in list_);
