    } else {
        return '';
    }
}

""" Coefficient for the 1PN tidal correction to h_22 mode
   Defined in arXiv:1203.4352, eqn A15
   Input
     X -- mass fraction of object being tidally deformed
   Output
     double, coeff for 1PN tidal correction to h_22 mode """
def Beta22_1(X: float) -> float {
    return (-202.0 + 560.0 * X - 340.0 * X * X + 45.0 * X * X * X) / 42.0 / (3.0 - 2.0 * X);
}

"""Turn a duration in seconds into a human readable string"""
def duration(s: int) -> str {
    (m, s) = divmod(s, 60);
    (h, m) = divmod(m, 60);
    (d, h) = divmod(h, 24);
    parts = [];
    if d {
        parts.append('%dd' % d);
    }
    if h {
        parts.append('%dh' % h);
    }
    if m {
        parts.append('%dm' % m);
    }
    if s {
        parts.append('%ds' % s);
    }
    return ' '.join(parts);
}

