"""
    Simple implementation of math.comb for python 3.7 compatibility.
    """
def choose(n: int, k: int) -> int {
    if 0 <= k <= n {
        ntok = 1;
        ktok = 1;
        for t in range(1, min(k, n - k) + 1) {
            ntok *= n;
            ktok *= t;
            n -= 1;
        }
        return ntok // ktok;
    } else {
        return 0;
    }
}

"""
    Merges two dictionaries, non-destructively, combining
    values on duplicate keys as defined by the optional merge
    function.  The default behavior replaces the values in d1
    with corresponding values in d2.  (There is no other generally
    applicable merge strategy, but often you'll have homogeneous
    types in your dicts, so specifying a merge technique can be
    valuable.)

    Examples:

    >>> d1 = {'a': 1, 'c': 3, 'b': 2}
    >>> d2 = merge_dict(d1, d1)
    >>> len(d2)
    3
    >>> [d2[k] for k in ['a', 'b', 'c']]
    [1, 2, 3]

    >>> d3 = merge_dict(d1, d1, lambda x,y: x+y)
    >>> len(d3)
    3
    >>> [d3[k] for k in ['a', 'b', 'c']]
    [2, 4, 6]

    """
def merge_dict(d1: any, d2: any, merge: any = lambda (x: any, y: any) { y; }) -> any {
    if not isinstance(d1, dict) {
        return merge(d1, d2);
    }
    result = dict(d1);
    if d2 is None {
        return result;
    }
    for (k, v) in list(d2.items()) {
        if k in result {
            result[k] = merge_dict(result[k], v, merge=merge);
        } else {
            result[k] = v;
        }
    }
    return result;
}

