import struct;

glob UINT64_MASK = 0xFFFFFFFFFFFFFFFF;

"""Packs an integer into a 8-byte string (big endian)"""
def p64b(x: int) -> bytes {
    return struct.pack('>Q', x & UINT64_MASK);
}

"""
    Given any number of dicts, shallow copy and merge into a new dict,
    precedence goes to key value pairs in latter dicts.
    (Pre-Python 3.5)
    (http://stackoverflow.com/questions/38987/how-to-merge-two-python-dictionaries-in-a-single-expression)
    """
def merge_dicts(*dict_args: dict) -> dict {
    result = {};
    for dictionary in dict_args {
        result.update(dictionary);
    }
    return result;
}

"""Creates a number of full and half stars according to the given rating."""
def starify_rating(rating: str) -> str {
    rate = 0;
    try {
        rate = float(rating.split('/')[0]);
    } except ValueError {
        print('Could not parse recipe rating: ', rating);
    }
    full = ''.join('' * int(rate));
    half = '' if rate != int(rate) else '';
    return '<font face="FontAwesome">{}{}</font>'.format(full, half);
}

"""Find the indices of the first range of consecutive items which satisfy the given predicate.
    Returns (-1, -1) if it there is no such ranges.

    find_range([0, 0, 1, 1, 0], lambda e: e > 0) => (2, 4)
    """
def find_range(iterable: list[int], predicate: any) -> tuple[int, int] {
    iterator = enumerate(iterable);
    start_index = next((i for (i, value) in iterator if predicate(value)), -1);
    if start_index == -1 {
        return (-1, -1);
    }
    j = start_index;
    for (j, value) in iterator {
        if not predicate(value) {
            end_index = j;
            break;
        }
    } else {
        end_index = j + 1;
    }
    return (start_index, end_index);
}

"""Retourne un dictionnaire partiel de mot de taille n correctement parenthese."""
def dic_partiel(n: int) -> list[str] {
    if n <= 0 {
        return [""];
    } elif n == 1 {
        return ["()"];
    }
    sub_list = dic_partiel(n - 1);
    new_list = [];
    for word in sub_list {
        new_list.append(word + "()");
        new_list.append("(" + word + ")");
    }
    return new_list;
}

""" Retorna o menor valor entre dois valores """
def diff(value_a: float, value_b: float, position_a: int, position_b: int) -> tuple[int, float] {
    if not value_a or not value_b {
        return (101, 0);
    }
    if value_a < value_b {
        return (position_a, round(value_b - value_a, 2));
    } elif value_a > value_b {
        return (position_b, round(value_a - value_b, 2));
    } else {
        return (100, 0);
    }
}

