"""Returns [[trues], [falses]], where [trues] is the items in
    'iterable' that satisfy 'pred' and [falses] is all the rest."""
def partition(pred: any, iterable: list[any]) -> tuple[list[any], list[any]] {
    trues = [];
    falses = [];
    for item in iterable {
        if pred(item) {
            trues.append(item);
        } else {
            falses.append(item);
        }
    }
    return (trues, falses);
}

""" Indicates if the char is upper """
def isupper(char: str) -> bool {
    if len(char) == 1 {
        if ord(char) >= 0x41 and ord(char) <= 0x5A {
            return True;
        }
    }
    return False;
}

