"""
        Distributes items into n (almost) equally large batches.
        Example: items = [1,2,3,4,5,6,7,8,9], n = 4 gives batches = [[1,5,9], [2,6], [3,7], [4,8]]

        Args:
            items (list[any]): List of items of any type
            n (int): Number of max items of a batch

        Returns:
            list[list[any]]: List of lists of items of any type
    """
def distribute(items: list[any], n: int) -> list[list[any]] {
    batches = [[] for _ in range(n)];
    for (i, item) in enumerate(items) {
        batches[i % n].append(item);
    }
    return [b for b in batches if not len(b) == 0];
}

"""Return AP (Average Precision) given target tags and retrieved results."""
def AP(target: list[str], results: list[list[str]]) -> float {
    n = 1;
    hit = 0;
    ap = 0;
    len_target = len(target);
    for res in results {
        (small_set, big_set) = (target, res) if len_target < len(res) else (res, target);
        for item in small_set {
            if item in big_set {
                hit += 1;
                ap += hit / n;
                break;
            }
        }
        n += 1;
    }
    return ap / hit;
}

"""Convert an object to string and surround in parenthesis if it contains an operator."""
def _maybe_parenthesise(x: int | float, convert: type = str) -> str {
    warrenters = '+*/\\-^';
    ret = convert(x);
    if any(w in ret for w in warrenters) {
        return "(" + ret + ")";
    }
    return ret;
}

