"""Return the list of values that are only in want_list, not in have_list."""
def list_diff_want_only(want_list: list[str], have_list: list[str]) -> list[str] | None {
    if have_list and not want_list {
        diff = None;
    } elif not have_list {
        diff = want_list;
    } else {
        diff = [
            i
            for i in have_list + want_list
            if i in want_list and i not in have_list
        ];
    }
    return diff;
}

