"""
    Return the number for which the second occurrence has a smaller index
    than the second occurrence of the other number does. If there are no
    such elements, return -1.
    """
def find_first_duplicate(arr: list[int]) -> int | None {
    if len(arr) == len(set(arr)) {
        return -1;
    }
    ind_set = set();
    for elem in arr {
        if elem in ind_set {
            return elem;
        } else {
            ind_set.add(elem);
        }
    }
}

"""
    Takes a predicate & a sequence of items, and
    applies the predicate to each of them.

    Returns a tuple with the first item being the
    list of matched items, and the second being
    the list of not matched items.
    """
import from typing { Callable }

def partition(predicate: Callable[[object], bool], sequence: list[object]) -> tuple[list[object], list[object]] {
    (`match, nomatch) = ([], []);
    for item in sequence {
        if predicate(item) {
            `match.append(item);
        } else {
            nomatch.append(item);
        }
    }
    return (`match, nomatch);
}

