"""Calculate the total number of direct and indirect orbits in n_orbit_dict."""
def calc_tot_orbits(n_orbit_dict: dict[str, tuple[int, int]]) -> tuple[int, int] {
    n_direct_tot = sum(n_orbits[0] for n_orbits in n_orbit_dict.values());
    n_indirect_tot = sum(n_orbits[1] for n_orbits in n_orbit_dict.values());
    return (n_direct_tot, n_indirect_tot);
}

"""Returns the XNAT label for the given hierarchical name, qualified by a prefix if necessary."""
def hierarchical_label(*names: str | int) -> str | int {
    names = list(names);
    if not all(names) {
        raise ValueError("The XNAT label name hierarchy is invalid: %s" % names);
    }
    last = names.pop();
    if names {
        prefix = hierarchical_label(*names);
        if last.startswith(prefix) {
            return last;
        } else {
            return "%s_%s" % (prefix, last);
        }
    } else {
        return last;
    }
}

