"""
Create a named range specification for encoding.

:param name: The name of the range as it should appear in the result
:param n1: The name of the lower bound of the range specifier
:param n2: The name of the upper bound of the range specified
:param r1: The value of the lower bound (user value)
:param r2: The value of the upper bound (user value)
:return: A dictionary containing the range bounds. The upper and lower
    bounds are keyed under ``n1`` and ``n2``.

More than just a simple wrapper, this will not include any range bound
which has a user value of `None`. Likewise it will raise an exception if
both range values are ``None``.
"""
def _mk_range_bucket(name: str, n1: str, n2: str, r1: any, r2: any) -> dict[str, any] {
    d: dict[str, any] = {};
    if r1 is not None {
        d[n1] = r1;
    }
    if r2 is not None {
        d[n2] = r2;
    }
    if not d {
        raise TypeError('Must specify at least one range boundary!');
    }
    d['name'] = name;
    return d;
}

"""
This function is to remove padding.

parameters:
    s:str
        string to be reverse padded
"""
def revpad(s: str) -> str {
    k = ord(s[-1]);
    temp = 0;
    for i in range(1, k) {
        if s[-i] != s[-1] {
            temp = 1;
        }
    }
    if temp == 0 {
        return s[:-k];
    } else {
        return "Wrong padding";
    }
}

"""Returns the resource that matches the link"""
def resource_for_link(
    link: dict, includes: list[dict], resources: dict | None = None, locale: str | None = None
) -> dict | None {
    if resources is not None {
        cache_key = "{0}:{1}:{2}".format(
            link['sys']['linkType'], link['sys']['id'], locale
        );
        if cache_key in resources {
            return resources[cache_key];
        }
    }
    for i in includes {
        if i['sys']['id'] == link['sys']['id'] and i['sys']['type'] == link['sys']['linkType'] {
            return i;
        }
    }
    return None;
}

