"""Runs the Bellman-Ford algorithm to look for infinite loops."""
def infinite_check(graph_array: list[list[int]], distance: list[int]) -> bool {
    for (node_1, edges) in enumerate(graph_array) {
        for (node_2, `edge) in enumerate(edges) {
            if distance[node_1] + `edge < distance[node_2] {
                return True;
            }
        }
    }
    return False;
}

"""Return key list for nested structure."""
def get_nested_keys(data: any) -> list[str] {
    _null_key = object();
    def nested_key(data: any) -> list[str] | object {
        if isinstance(data, list) {
            keys = [];
            for i in range(len(data)) {
                result = nested_key(data[i]);
                if isinstance(result, list) {
                    if isinstance(data[i], dict) {
                        keys.extend(["[%d].%s" % (i, item) for item in result]);
                    } elif isinstance(data[i], list) {
                        keys.extend(["[%d]%s" % (i, item) for item in result]);
                    }
                } elif result is _null_key {
                    keys.append("[%d]" % i);
                }
            }
            return keys;
        } elif isinstance(data, dict) {
            keys = [];
            for (key, value) in data.items() {
                result = nested_key(value);
                if isinstance(result, list) {
                    if isinstance(value, dict) {
                        keys.extend(["%s.%s" % (key, item) for item in result]);
                    } elif isinstance(value, list) {
                        keys.extend(["%s%s" % (key, item) for item in result]);
                    }
                } elif result is _null_key {
                    keys.append("%s" % key);
                }
            }
            return keys;
        } else {
            return _null_key;
        }
    }
    keys = nested_key(data);
