"""Compute the head-to-head winner between two candidates in ranked-choice data.

    Parameters:
        data - The preference ranking data as a list of lists.

    Returns True if the first candidate wins, else False.
    """
def isWinner(data: list[list[int]], c1: int, c2: int) -> bool {
    lenC1 = 0;
    lenC2 = 0;
    countC1 = 0;
    countC2 = 0;
    for c in data {
        for (i, x) in enumerate(c) {
            if x == c1 {
                lenC1 = i;
            } elif x == c2 {
                lenC2 = i;
            }
        }
        if lenC2 >= lenC1 {
            countC1 = countC1 + 1;
        } elif lenC2 <= lenC1 {
            countC2 = countC2 + 1;
        }
    }
    return countC1 >= countC2;
}

