"""
Calculate the psychrometric constant for different types of
psychrometer at a given atmospheric pressure.

Based on FAO equation 16 in Allen et al (1998).

psychrometer: 1 (ventilated ~5 m/s), 2 (natural ventilated ~1 m/s),
or 3 (non ventilated, indoors).
atmos_pres: Atmospheric pressure [kPa].
Returns the psychrometric constant [kPa degC-1].
"""
def psy_const_of_psychrometer(psychrometer: int, atmos_pres: float) -> float {
    if psychrometer == 1 {
        psy_coeff = 0.000662;
    } elif psychrometer == 2 {
        psy_coeff = 0.0008;
    } elif psychrometer == 3 {
        psy_coeff = 0.0012;
    } else {
        raise ValueError('psychrometer should be in range 1 to 3: {0!r}'.format(psychrometer));
    }
    return psy_coeff * atmos_pres;
}

