"""
Decodes html encoded emails
Pass a list of emails
Decodes email if starting characters are '&#'
Returns list of unencoded emails
"""
def decrypt(lst: list[str]) -> list[str] {
    while True {
        unencoded_emails = [];
        for string in lst {
            if string[0:2] == '&#' {
                slices = int(len(string) / 6);
                count = 0;
                starting_pos = 0;
                decoded_email = '';
                while count < slices {
                    decoded_email = (
                        decoded_email
                        + chr(int(string[starting_pos + 2:starting_pos + 5]))
                    );
                    count += 1;
                    starting_pos += 6;
                }
                unencoded_emails.append(decoded_email);
            } else {
                unencoded_emails.append(string);
            }
        }
        return unencoded_emails;
    }
}

"""Set figure dimensions to avoid scaling in LaTeX.

Parameters
----------
width: float or string
        Document width in points, or string of predined document type
fraction: float, optional
        Fraction of the width which you wish the figure to occupy
subplots: array-like, optional
        The number of rows and columns of subplots.
Returns
-------
fig_dim: tuple
        Dimensions of figure in inches
"""
def set_size(width: float | str, fraction: float = 1, subplots: tuple[int, int] = (1, 1)) -> tuple[float, float] {
    if width == 'thesis' {
        width_pt = 426.79135;
    } elif width == 'beamer' {
        width_pt = 307.28987;
    } elif width == 'pnas' {
        width_pt = 246.09686;
    } elif width == 'current' {
        width_pt = 469.75499;
    } else {
        width_pt = width;
    }
    fig_width_pt = width_pt * fraction;
    inches_per_pt = 1 / 72.27;
    golden_ratio = (5 ** 0.5 - 1) / 2;
    fig_width_in = fig_width_pt * inches_per_pt;
    fig_height_in = fig_width_in * golden_ratio * (subplots[0] / subplots[1]);
    return (fig_width_in, fig_height_in);
}

