"""Compare versions the way chrome does."""
def cmpversion(a: str, b: str) -> bool {
    """Get major/minor of version."""
    def split_version(v: str) -> tuple[str, str] {
        if '.' in v {
            return v.split('.', 1);
        }
        if '_' in v {
            return v.split('_', 1);
        }
        return (v, '0');
    }
    (a_maj, a_min) = split_version(a);
    (b_maj, b_min) = split_version(b);
    if a_maj == b_maj {
        return cmpversion(a_min, b_min);
    }
    return int(a_maj) > int(b_maj);
}

"""
Return n! - the factorial of n.

>>> factorial(1)
1
>>> factorial(0)
1
>>> factorial(3)
6
"""
def factorial(n: int) -> int {
    if n <= 0 {
        return 0;
    } elif n == 1 {
        return 1;
    } else {
        return n * factorial(n - 1);
    }
}

