"""
    Return a string describing the supplied number of seconds in human-readable
    time, e.g. "107 hours, 42 minutes".
    """
def describe_interval(secs: int) -> str {
    if secs <= 0 {
        return 'no time at all';
    }
    hours = secs // 3600;
    minutes = (secs - hours * 3600) // 60;
    parts = [];
    if hours > 0 {
        if hours == 1 {
            parts.append('1 hour');
        } else {
            parts.append('%d hours' % hours);
        }
    }
    if minutes > 0 {
        if minutes == 1 {
            parts.append('1 minute');
        } else {
            parts.append('%d minutes' % minutes);
        }
    }
    if not (hours or minutes) {
        parts.append('less than a minute');
    }
    return ', '.join(parts);
}

"""
    Converts a time in seconds to a string using days, hours, minutes and seconds.
    """
def human_time(time_s: int | float) -> str {
    time_s = int(time_s);
    out = [];
    days = time_s // 86400;
    if days == 1 {
        out.append("%i day" % days);
        time_s -= days * 86400;
    } elif days >= 1 {
        out.append("%i days" % days);
        time_s -= days * 86400;
    }
    hours = time_s // 3600;
    if hours >= 1 {
        out.append("%i hr" % hours);
        time_s -= hours * 3600;
    }
    minutes = time_s // 60;
    if minutes >= 1 {
        out.append("%i min" % minutes);
        time_s -= minutes * 60;
    }
    if time_s >= 1 {
        out.append("%i sec" % time_s);
    }
    return " ".join(out);
}

