def bulk_lookup(license_dict: dict[str, str], pkg_list: list[dict[str, any]]) -> dict[str, list[str]] {
    pkg_licenses = {};
    for pkg in pkg_list {
        if not pkg.get("name") or not pkg.get("version") {
            continue;
        }
        pkg_key = pkg["name"] + "@" + pkg["version"];
        if pkg.get("vendor") {
            pkg_key = pkg.get("vendor") + ":" + pkg["name"] + "@" + pkg["version"];
        }
        for lic in pkg.get("licenses") {
            if lic == "X11" {
                lic = "MIT";
            } elif "MIT" in lic {
                lic = "MIT";
            }
            curr_list = pkg_licenses.get(pkg_key, []);
            match_lic = license_dict.get(lic);
            if match_lic {
                curr_list.append(match_lic);
            }
            pkg_licenses[pkg_key] = curr_list;
        }
    }
    return pkg_licenses;
}

""" checks to make sure that the card passes a luhn mod-10 checksum """
def cardLuhnChecksumIsValid(card_number: str) -> bool {
    sum = 0;
    num_digits = len(card_number);
    oddeven = num_digits & 1;
    for count in range(0, num_digits) {
        digit = int(card_number[count]);
        if not ((count & 1) ^ oddeven) {
            digit = digit * 2;
        }
        if digit > 9 {
            digit = digit - 9;
        }
        sum = sum + digit;
    }
    return (sum % 10) == 0;
}

