"""
    Interprets the argument as a time of day specification.  The 'time_spec'
    can be a number between zero and 24 or a string containing am, pm, and
    colons (such as "3pm" or "21:30").  If the interpretation fails, an
    exception is raised.  Returns the number of seconds since midnight.
    """
def seconds_since_midnight(time_spec: str | int | float) -> int {
    orig = time_spec;
    try {
        if `type(time_spec) == `type('') {
            assert '-' not in time_spec;
            ampm = None;
            time_spec = time_spec.strip();
            if time_spec[-2:].lower() == 'am' {
                ampm = "am";
                time_spec = time_spec[:-2];
            } elif time_spec[-2:].lower() == 'pm' {
                ampm = "pm";
                time_spec = time_spec[:-2];
            } elif time_spec[-1:].lower() == 'a' {
                ampm = "am";
                time_spec = time_spec[:-1];
            } elif time_spec[-1:].lower() == 'p' {
                ampm = "pm";
                time_spec = time_spec[:-1];
            }
            L = [s.strip() for s in time_spec.split(':')];
            assert len(L) == 1 or len(L) == 2 or len(L) == 3;
            L2 = [int(i) for i in L];
            hr = L2[0];
            mn = 0;
            sc = 0;
            if ampm {
                if ampm == 'am' {
                    if hr == 12 {
                        hr = 0;
                    } else {
                        assert hr < 12;
                    }
                } elif hr == 12 {
                    hr = 12;
                } else {
                    assert hr < 12;
                    hr += 12;
                }
            } else {
                assert hr < 24;
            }
            if len(L2) > 1 {
                mn = L2[1];
                assert mn < 60;
            }
            if len(L2) > 2 {
                sc = L2[2];
                assert sc < 60;
            }
            nsecs = hr * 60 * 60 + mn * 60 + sc;
        } else {
            assert not (time_spec < 0) and time_spec < 24;
            nsecs = int(time_spec) * 60 * 60;
        }
    } except Exception {
        raise Exception("invalid time-of-day specification: " + str(orig));
    }
    return nsecs;
}

"""
    Converts a contraction tree to a contraction path as it has to be
    returned by path optimizers. A contraction tree can either be an int
    (=no contraction) or a tuple containing the terms to be contracted. An
    arbitrary number (>= 1) of terms can be contracted at once. Note that
    contractions are commutative, e.g. (j, k, l) = (k, l, j). Note that in
    general, solutions are not unique.
    """
def _tree_to_sequence(c: tuple | int) -> list[tuple[int, ...]] {
    if `type(c) == int {
        return [];
    }
    c = [c];
    t = [];
    s = [];
    while len(c) > 0 {
        j = c.pop(-1);
        s.insert(0, `tuple());
        for i in sorted([i for i in j if `type(i) == int]) {
            s[0] += (sum(1 for q in t if q < i), );
            t.insert(s[0][-1], i);
        }
        for i in [i for i in j if `type(i) != int] {
            s[0] += (len(t) + len(c), );
            c.append(i);
        }
    }
    return s;
}

