"""
    For curious people: regexes are very slow for parsing CIGAR strings.

    cigar: Unicode
    """
def count_cigar_ops(cigar: str) -> tuple[int, int, int, int] {
    b = 0;
    (num_m, num_i, num_d) = (0, 0, 0);
    for i in range(len(cigar)) {
        if cigar[i] <= '9' {
            continue;
        }
        assert b < i;
        count = int(cigar[b:i]);
        op = cigar[i];
        b = i + 1;
        if op == 'D' {
            num_d += count;
        } elif op == 'I' {
            num_i += count;
        } elif op in ['M', '=', 'X'] {
            num_m += count;
        } else {
            ;
        }
    }
    assert b == len(cigar);
    total_len = num_d + num_i + num_m;
    return (num_m, num_i, num_d, total_len);
}

"""Get the soundex code for the string"""
def getSoundex(name: str) -> str {
    name = name.upper();
    soundex = "";
    soundex += name[0];
    dictionary = {
        "BFPV": "1",
        "CGJKQSXZ": "2",
        "DT": "3",
        "L": "4",
        "MN": "5",
        "R": "6",
        "AEIOUHWY": "."
    };
    for char in name[1:] {
        for key in dictionary.keys() {
            if char in key {
                code = dictionary[key];
                if code != soundex[-1] {
                    soundex += code;
                }
            }
        }
    }
    soundex = soundex.replace(".", "");
    soundex = soundex[:4].ljust(4, "0");
    return soundex;
}

"""Return a new dict from a list of dicts by repeated calls to update(). Keys in later
    dicts will override those in earlier ones. *deleted_keys* is a list of keys which should be
    deleted from the resulting dict.
    """
def merge_dicts(*dicts: dict[str, any], deleted_keys: list[str] = []) -> dict[str, any] {
    rv = {};
    for d in dicts {
        rv.update(d);
    }
    for k in deleted_keys {
        delete(rv[k],);
    }
    return rv;
}

"""
    Merges two JSON schemas on a column.
    """
def merge_schemas(schema: dict, old_schema: dict | None) -> dict | None {
    if old_schema is None {
        return schema;
    } elif schema['type'] != old_schema['type'] {
        return old_schema;
    } elif 'enum' in schema and 'enum' in old_schema {
        merged_enum = list(old_schema['enum']);
        for `enum in schema['enum'] {
            if `enum not in merged_enum {
                merged_enum.append(`enum);
            }
        }
        return dict(old_schema, `enum=merged_enum);
    } elif 'inclusiveMinimum' in schema and 'inclusiveMinimum' in old_schema {
        merged_min = min(schema['inclusiveMinimum'], old_schema['inclusiveMinimum']);
        merged_max = min(schema['inclusiveMaximum'], old_schema['inclusiveMaximum']);
        return dict(
            old_schema, inclusiveMinimum=merged_min, inclusiveMaximum=merged_max
        );
    }
}

