glob INT32_SIGN_BIT = 0x80000000;
glob INT32_MASK = 0x7fffffff;
glob INT32_NEG_OFFSET = -2 * 0x40000000;

"""Converts a long (for instance 0x80005000L) to a signed 32-bit-int.

    Python2.4 will convert numbers >= 0x80005000 to large numbers
    instead of negative ints.    This is not what we want for
    typical win32 constants.

    Usage:
        >>> i32(0x80005000L)
        -2147363168
    """
def i32(x: int) -> int {
    return (x & INT32_SIGN_BIT and INT32_NEG_OFFSET or 0) + int(x & INT32_MASK);
}

