"""Update d with values from u, recursing into sub-dictionaries."""
def recursive_dict_update(d: dict[str, object], u: dict[str, object]) -> dict[str, object] {
    for (k, v) in u.items() {
        if isinstance(v, dict) {
            try {
                subdict = d[k].copy();
            } except KeyError {
                subdict = {};
            }
            d[k] = recursive_dict_update(subdict, v);
        } else {
            d[k] = v;
        }
    }
    return d;
}

